-- Presentation-only AP classification. Existing opening documents, original
-- currency calculations, payments, journal/GL values and AR remain unchanged.
do $$declare item record;begin
 for item in select * from(values
  ('public.run_aging_report(text,jsonb)','eaa776fe3e7f29d0fc30ea19d4ddaae6'),
  ('public.run_aging_report_before_consolidation(text,jsonb)','d3626155da1114ede7e8f11fce00d35b'),
  ('public.run_aging_report_before_original_currency_reconciliation(text,jsonb)','388489e9c216ac1afa6bdd25a774e78a'),
  ('public.aging_original_currency_breakdown(text,jsonb,boolean)','0abd497ac1e8cdb040926d40f09a0f03'),
  ('report_delivery_private.run_aging_report(text,jsonb)','c2e5030a3104e26660bf3b254e58bedb'),
  ('report_delivery_private.run_aging_report_before_consolidation(text,jsonb)','d2a74a23cc333ca6339f35be19531213'),
  ('report_delivery_private.run_aging_report_before_original_currency_reconciliation(text,jsonb)','388489e9c216ac1afa6bdd25a774e78a')
 )v(signature,source_md5)loop
  if not exists(select 1 from pg_proc where oid=to_regprocedure(item.signature)and md5(prosrc)=item.source_md5)then
   raise exception 'Unexpected payable aging calculation: %',item.signature;
  end if;
 end loop;
end$$;

create function report_delivery_private.payable_invoice_type_code(value text)returns text
language sql immutable set search_path=pg_catalog as $$
 select case value when'Factura estándar'then'STANDARD'when'Factura Expense'then'EXPENSE'
  when'Factura Tarjeta'then'CARD'when'Factura Caja Chica'then'PETTY_CASH'
  when'Factura Activos Fijos'then'FIXED_ASSET'else'OTHER'end
$$;
create function report_delivery_private.payable_invoice_type_label(value text)returns text
language sql immutable set search_path=pg_catalog,public,pg_temp as $$
 select case report_delivery_private.payable_invoice_type_code(value)
  when'STANDARD'then'Estándar'when'EXPENSE'then'Expense'when'CARD'then'Tarjeta'
  when'PETTY_CASH'then'Caja Chica'when'FIXED_ASSET'then'Activos Fijos'else'Otros / sin tipo'end
$$;
create function report_delivery_private.payable_invoice_type_filter(kind text,filters jsonb)returns text
language plpgsql immutable set search_path=pg_catalog,public,pg_temp as $$
declare value text;begin
 if kind is distinct from'AP'then return null;end if;
 value:=nullif(nullif(upper(btrim(coalesce(filters->>'payableInvoiceType','ALL'))),'ALL'),'');
 if value is not null and value not in('STANDARD','EXPENSE','CARD','PETTY_CASH','FIXED_ASSET','OTHER')then
  raise exception using errcode='22023',message='Seleccione un tipo válido de factura de proveedor.';
 end if;return value;
end$$;
create function report_delivery_private.payable_aging_type_summary(summary jsonb,filter_type text)returns jsonb
language sql immutable set search_path=pg_catalog,public,pg_temp as $$
 select summary||jsonb_build_object('typeFilterActive',filter_type is not null,'unallocatedAdvancesExcluded',filter_type is not null)
  ||case when filter_type is null then'{}'::jsonb else jsonb_build_object(
   'advances',0,'netBalance',summary->'subledger','controlBalance',null,'difference',null,
   'reconciliationAvailable',false,'reconciliationReason','INVOICE_TYPE_FILTER',
   'currencyBreakdown',coalesce((select jsonb_agg(item||jsonb_build_object('advances',0,'netBalance',item->'subledger',
    'controlBalance',null,'difference',null,'reconciliationAvailable',false,'reconciliationReason','INVOICE_TYPE_FILTER')order by position)
    from jsonb_array_elements(coalesce(summary->'currencyBreakdown','[]'::jsonb))with ordinality x(item,position)),'[]'::jsonb))end
$$;
create function report_delivery_private.payable_aging_advance_entities(filters jsonb,local_mode boolean)returns jsonb
language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$
declare
 sid bigint:=nullif(filters->'subsidiaryIds'->>0,'')::bigint;cutoff date:=nullif(filters->>'dateTo','')::date;
 entity_key bigint:=nullif(filters->>'agingEntityId','')::bigint;book_key bigint:=nullif(filters->>'bookId','')::bigint;
 category_value text:=nullif(filters->>'supplierCategory','');result jsonb;
begin
 if sid is null or cutoff is null or(auth.jwt()->>'role'is distinct from'service_role'and not exists(
  select 1 from public.user_subsidiaries where user_id=public.app_user_id()and subsidiary_id=sid))then
  raise exception using errcode='42501',message='Seleccione una subsidiaria autorizada y fecha de corte.';
 end if;
 if nullif(filters->>'costCenterId','')is not null then return'[]'::jsonb;end if;
 with advances as(
  select payment.supplier_id entity_id,supplier.supplier_number entity_code,supplier.company_name entity_name,
   case when local_mode then subsidiary.currency_id else coalesce(payment.currency_id,tran.currency_id,subsidiary.currency_id)end currency_id,
   sum(greatest(payment.amount_paid-coalesce(application.applied,0),0)
    *case when local_mode then coalesce(nullif(tran.exchange_rate,0),1)else 1 end)amount
  from public.supplier_payment payment join public."transaction"tran using(transaction_id)
  join public.subsidiaries subsidiary using(subsidiary_id)join public.suppliers supplier on supplier.supplier_id=payment.supplier_id
  left join lateral(select sum(item.amount)applied from public.supplier_payment_application item
   where item.payment_id=payment.payment_id and item.application_date<=cutoff)application on true
  where tran.subsidiary_id=sid and tran.tran_date<=cutoff
   and(entity_key is null or payment.supplier_id=entity_key)
   and(category_value is null or supplier.supplier_category=category_value)
   and(book_key is null or exists(select 1 from public.gl_impact impact where impact.transaction_id=tran.transaction_id and impact.accounting_book_id=book_key))
  group by payment.supplier_id,supplier.supplier_number,supplier.company_name,
   case when local_mode then subsidiary.currency_id else coalesce(payment.currency_id,tran.currency_id,subsidiary.currency_id)end
 )select coalesce(jsonb_agg(jsonb_build_object('subsidiaryId',sid,'entityId',entity_id,'entityCode',entity_code,'entityName',entity_name,
   'currencyId',currency.currency_id,'currencyCode',currency.currency_code,'amount',amount)order by entity_name,entity_id,currency.currency_code),'[]'::jsonb)
  into result from advances join public.currencies currency using(currency_id)where amount<>0;
 return result;
end$$;
create function report_delivery_private.merge_payable_invoice_type_totals(items jsonb)returns jsonb
language sql immutable set search_path=pg_catalog,public,pg_temp as $$
 with totals as(
  select item->>'invoiceTypeCode'code,item->>'invoiceTypeLabel'label,(item->>'currencyId')::bigint currency_id,item->>'currencyCode'currency_code,
   sum((item->>'documentCount')::bigint)document_count,sum((item->>'originalAmount')::numeric)original_amount,
   sum((item->>'appliedAmount')::numeric)applied_amount,sum((item->>'pending')::numeric)pending,
   sum((item#>>'{buckets,CURRENT}')::numeric)current_amount,sum((item#>>'{buckets,1_30}')::numeric)amount_1_30,
   sum((item#>>'{buckets,31_60}')::numeric)amount_31_60,sum((item#>>'{buckets,61_90}')::numeric)amount_61_90,
   sum((item#>>'{buckets,91_120}')::numeric)amount_91_120,sum((item#>>'{buckets,OVER_120}')::numeric)amount_over_120
  from jsonb_array_elements(coalesce(items,'[]'::jsonb))x(item)
  group by item->>'invoiceTypeCode',item->>'invoiceTypeLabel',item->>'currencyId',item->>'currencyCode'
 )select coalesce(jsonb_agg(jsonb_build_object('invoiceTypeCode',code,'invoiceTypeLabel',label,'currencyId',currency_id,'currencyCode',currency_code,
  'documentCount',document_count,'originalAmount',original_amount,'appliedAmount',applied_amount,'pending',pending,
  'buckets',jsonb_build_object('CURRENT',current_amount,'1_30',amount_1_30,'31_60',amount_31_60,'61_90',amount_61_90,'91_120',amount_91_120,'OVER_120',amount_over_120))
  order by case code when'STANDARD'then 1 when'EXPENSE'then 2 when'CARD'then 3 when'PETTY_CASH'then 4 when'FIXED_ASSET'then 5 else 6 end,currency_code),'[]'::jsonb)from totals
$$;

