  definition:=pg_get_functiondef((target->>'signature')::regprocedure);
  for patch in select value from jsonb_array_elements(target->'patches')loop
   start_at:=case when patch?'start'then strpos(definition,patch->>'start')else 1 end;
   end_at:=case when patch?'end'then strpos(substr(definition,start_at),patch->>'end')+start_at-1 else length(definition)+1 end;
   if start_at<1 or end_at<start_at then raise exception 'Unexpected payable aging patch region: %',target->>'signature';end if;
   part:=substr(definition,start_at,end_at-start_at);
   occurrences:=(length(part)-length(replace(part,patch->>'needle','')))/length(patch->>'needle');
   if occurrences<>coalesce((patch->>'count')::integer,1)then raise exception 'Unexpected payable aging patch boundary: %',target->>'signature';end if;
   next_part:=replace(part,patch->>'needle',patch->>'replacement');
   definition:=overlay(definition placing next_part from start_at for end_at-start_at);
  end loop;
  execute definition;
 end loop;
end$payable_types$;
